package com.rectorplus.app;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.nio.file.Files;import java.security.*;import java.util.zip.*;
public class ReleasePolicyTest {
 @Test public void neverActivatesAnIncompatibleRelease(){assertTrue(ReleasePolicy.compatible(1,1,1,1,1));assertFalse(ReleasePolicy.compatible(1,1,2,4,1));assertFalse(ReleasePolicy.compatible(1,1,1,4,2));assertFalse(ReleasePolicy.compatible(5,1,1,4,1));}
 @Test public void rejectsOlderAndFailedBuilds(){assertTrue(ReleasePolicy.newer(1,2,0));assertFalse(ReleasePolicy.newer(2,1,0));assertFalse(ReleasePolicy.newer(1,1,0));assertFalse(ReleasePolicy.newer(1,2,2));}
 @Test public void verifiesManifestSignatureAndRefusesModification()throws Exception{KeyPairGenerator generator=KeyPairGenerator.getInstance("RSA");generator.initialize(2048);KeyPair pair=generator.generateKeyPair();byte[] payload="release-1".getBytes("UTF-8");Signature signer=Signature.getInstance("SHA256withRSA");signer.initSign(pair.getPrivate());signer.update(payload);byte[] signature=signer.sign();assertTrue(ReleasePolicy.verify(payload,signature,pair.getPublic().getEncoded()));assertFalse(ReleasePolicy.verify("release-2".getBytes("UTF-8"),signature,pair.getPublic().getEncoded()));}
 private File archive(String name)throws Exception{File zip=File.createTempFile("rectorplus-test-",".zip");try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(zip))){out.putNextEntry(new ZipEntry(name));out.write("test".getBytes("UTF-8"));out.closeEntry();}return zip;}
 @Test public void refusesTraversalAndNativeExecutableFiles()throws Exception{for(String name:new String[]{"../outside.html","/absolute.js","bad.dex","lib/plugin.so","C:/bad.js"}){File directory=Files.createTempDirectory("rectorplus-test").toFile(),zip=archive(name);try{ReleasePolicy.unpack(zip,directory);fail("Unsafe archive accepted: "+name);}catch(IOException expected){}finally{zip.delete();}}}
 @Test public void requiresCompleteWebEntryPoint()throws Exception{File directory=Files.createTempDirectory("rectorplus-test").toFile(),zip=archive("assets/app.js");try{ReleasePolicy.unpack(zip,directory);fail("Missing entry accepted");}catch(IOException expected){}finally{zip.delete();}}
}
